window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d5d5e89790d2d945"]={"versions": [{"id": "FIG-d5d5e89790d2d945", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des PDU Routers (AUTOSAR Classic Platform, Communication Services). Das Diagramm veranschaulicht das Gateway-Routing einer segmentierten Transportprotokoll-I-PDU (Multi-N-PDU) von einem Quell-Transportprotokoll (J1939Tp) zu zwei Ziel-Transportprotokollen (CanTp und LinTp) mit paralleler lokaler Bereitstellung an das Diagnosemodul (Dcm).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Komponenten (als UML-Module mit Lebenslinien):</p>\n<ul class=\"fig-list\">\n<li><code>Dcm</code> (Diagnostic Communication Manager, obere Schicht / Anwender)</li>\n<li><code>PduR</code> (PDU Router)</li>\n<li><code>J1939Tp</code> (SAE J1939 Transport Layer / Quell-TP)</li>\n<li><code>CanTp</code> (CAN Transport Layer / 1. Ziel-TP)</li>\n<li><code>LinTp</code> (LIN Transport Layer / 2. Ziel-TP)</li>\n</ul>\n<p class=\"fig-p\">Verwendete C-Schnittstellenfunktionen:</p>\n<ul class=\"fig-list\">\n<li>Quell-Empfang: <code>PduR_J1939TpStartOfReception</code>, <code>PduR_J1939TpCopyRxData</code>, <code>PduR_J1939TpRxIndication</code></li>\n<li>Lokaler Empfang (Dcm): <code>Dcm_StartOfReception</code>, <code>Dcm_CopyRxData</code>, <code>Dcm_TpRxIndication</code></li>\n<li>Ziel-Sendeanforderung: <code>CanTp_Transmit</code>, <code>LinTp_Transmit</code></li>\n<li>Ziel-Datenabruf und Bestätigung: <code>PduR_CanTpCopyTxData</code>, <code>PduR_LinTpCopyTxData</code>, <code>PduR_CanTpTxConfirmation</code>, <code>PduR_LinTpTxConfirmation</code></li>\n<li>Interne Pufferverwaltung: <code>copy data()</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf gliedert sich in drei Phasen:</p>\n<ol class=\"fig-list\">\n<li><strong>Empfang und Routing-Initialisierung (J1939Tp -> PduR):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>J1939Tp</code> ruft <code>PduR_J1939TpStartOfReception(...)</code> auf; <code>PduR</code> allokiert Pufferressourcen.</li>\n<li>Erstes Datenpaket wird via <code>PduR_J1939TpCopyRxData(...)</code> an <code>PduR</code> übergeben und intern zwischengespeichert (<code>copy data()</code>).</li>\n<li><code>PduR</code> stößt parallel die Transmissionen auf den Zielbussen an: Aufruf von <code>CanTp_Transmit(...)</code> (\"Transmit on CAN\") und <code>LinTp_Transmit(...)</code> (\"Transmit on LIN\").</li>\n<li>Nach Erhalt aller Eingangssegmente signalisiert <code>J1939Tp</code> den Abschluss mittels <code>PduR_J1939TpRxIndication(..., E_OK)</code> (\"Complete data received from J1939Tp\").</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Lokale Weiterleitung an Dcm (PduR -> Dcm):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Sobald die Gesamtnachricht im PduR vorliegt, initiiert <code>PduR</code> die Übergabe an das Diagnosemodul via <code>Dcm_StartOfReception(...)</code>.</li>\n<li>In aufeinanderfolgenden Schritten kopiert <code>Dcm</code> die Segmente via <code>Dcm_CopyRxData(...)</code> aus dem PduR-Puffer in den eigenen Puffer (<code>copy data()</code>).</li>\n<li>Der Transfer an den Dcm wird mit <code>Dcm_TpRxIndication(...)</code> erfolgreich abgeschlossen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Ziel-Ausgabe und Bestätigung (CanTp & LinTp):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die Zielmodule fordern die Nutzdaten schrittweise via TP-CopyTxData an: <code>PduR_CanTpCopyTxData(...)</code> (\"Data is requested on CAN\") und <code>PduR_LinTpCopyTxData(...)</code> (\"Data is requested on LIN\").</li>\n<li>PduR bedient die Datenanforderungen sequenziell / interleaved aus dem Puffer (<code>copy data()</code>).</li>\n<li>Nach vollständigem Versand senden beide Transportmodule ihre Quittierung an den Router: <code>PduR_CanTpTxConfirmation(...)</code> und <code>PduR_LinTpTxConfirmation(...)</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert das 1:n-Gatewaying sowie 1:n-Multicasting für segmentierte TP-Kommunikation nach dem Store-and-Forward- bzw. Puffer-Prinzip im PduR:</p>\n<ul class=\"fig-list\">\n<li>Transmissionen auf den Ziel-TPs werden bereits während des laufenden Empfangs getriggert (<code>CanTp_Transmit</code> / <code>LinTp_Transmit</code> nach erstem <code>CopyRxData</code>).</li>\n<li>Die lokale Weiterleitung an das Dcm (<code>Dcm_StartOfReception</code>) startet erst nach vollständigem Abschluss des Eingangs-TP-Transfers (<code>PduR_J1939TpRxIndication</code>).</li>\n<li>PduR puffert die Gesamt-PDU, um unterschiedliche Busgeschwindigkeiten, Segmentierungsgrößen und Bestätigungszeitpunkte von CanTp, LinTp und Dcm zu entkoppeln. Pufferfreigabe darf erst nach Eingang aller TxConfirmations bzw. RxIndications erfolgen.</li>\n</ul>"}, {"id": "FIG-225a438c0589146b", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des PDU Routers (AUTOSAR Classic Platform, Communication Services). Das Diagramm veranschaulicht das Gateway-Routing einer segmentierten Transportprotokoll-I-PDU (Multi-N-PDU) von einem Quell-Transportprotokoll (J1939Tp) zu zwei Ziel-Transportprotokollen (CanTp und LinTp) mit paralleler lokaler Bereitstellung an das Diagnosemodul (Dcm).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Komponenten (als UML-Module mit Lebenslinien):</p>\n<ul class=\"fig-list\">\n<li><code>Dcm</code> (Diagnostic Communication Manager, obere Schicht / Anwender)</li>\n<li><code>PduR</code> (PDU Router)</li>\n<li><code>J1939Tp</code> (SAE J1939 Transport Layer / Quell-TP)</li>\n<li><code>CanTp</code> (CAN Transport Layer / 1. Ziel-TP)</li>\n<li><code>LinTp</code> (LIN Transport Layer / 2. Ziel-TP)</li>\n</ul>\n<p class=\"fig-p\">Verwendete C-Schnittstellenfunktionen:</p>\n<ul class=\"fig-list\">\n<li>Quell-Empfang: <code>PduR_J1939TpStartOfReception</code>, <code>PduR_J1939TpCopyRxData</code>, <code>PduR_J1939TpRxIndication</code></li>\n<li>Lokaler Empfang (Dcm): <code>Dcm_StartOfReception</code>, <code>Dcm_CopyRxData</code>, <code>Dcm_TpRxIndication</code></li>\n<li>Ziel-Sendeanforderung: <code>CanTp_Transmit</code>, <code>LinTp_Transmit</code></li>\n<li>Ziel-Datenabruf und Bestätigung: <code>PduR_CanTpCopyTxData</code>, <code>PduR_LinTpCopyTxData</code>, <code>PduR_CanTpTxConfirmation</code>, <code>PduR_LinTpTxConfirmation</code></li>\n<li>Interne Pufferverwaltung: <code>copy data()</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf gliedert sich in drei Phasen:</p>\n<ol class=\"fig-list\">\n<li><strong>Empfang und Routing-Initialisierung (J1939Tp -> PduR):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>J1939Tp</code> ruft <code>PduR_J1939TpStartOfReception(...)</code> auf; <code>PduR</code> allokiert Pufferressourcen.</li>\n<li>Erstes Datenpaket wird via <code>PduR_J1939TpCopyRxData(...)</code> an <code>PduR</code> übergeben und intern zwischengespeichert (<code>copy data()</code>).</li>\n<li><code>PduR</code> stößt parallel die Transmissionen auf den Zielbussen an: Aufruf von <code>CanTp_Transmit(...)</code> (\"Transmit on CAN\") und <code>LinTp_Transmit(...)</code> (\"Transmit on LIN\").</li>\n<li>Nach Erhalt aller Eingangssegmente signalisiert <code>J1939Tp</code> den Abschluss mittels <code>PduR_J1939TpRxIndication(..., E_OK)</code> (\"Complete data received from J1939Tp\").</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Lokale Weiterleitung an Dcm (PduR -> Dcm):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Sobald die Gesamtnachricht im PduR vorliegt, initiiert <code>PduR</code> die Übergabe an das Diagnosemodul via <code>Dcm_StartOfReception(...)</code>.</li>\n<li>In aufeinanderfolgenden Schritten kopiert <code>Dcm</code> die Segmente via <code>Dcm_CopyRxData(...)</code> aus dem PduR-Puffer in den eigenen Puffer (<code>copy data()</code>).</li>\n<li>Der Transfer an den Dcm wird mit <code>Dcm_TpRxIndication(...)</code> erfolgreich abgeschlossen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Ziel-Ausgabe und Bestätigung (CanTp & LinTp):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die Zielmodule fordern die Nutzdaten schrittweise via TP-CopyTxData an: <code>PduR_CanTpCopyTxData(...)</code> (\"Data is requested on CAN\") und <code>PduR_LinTpCopyTxData(...)</code> (\"Data is requested on LIN\").</li>\n<li>PduR bedient die Datenanforderungen sequenziell / interleaved aus dem Puffer (<code>copy data()</code>).</li>\n<li>Nach vollständigem Versand senden beide Transportmodule ihre Quittierung an den Router: <code>PduR_CanTpTxConfirmation(...)</code> und <code>PduR_LinTpTxConfirmation(...)</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert das 1:n-Gatewaying sowie 1:n-Multicasting für segmentierte TP-Kommunikation nach dem Store-and-Forward- bzw. Puffer-Prinzip im PduR:</p>\n<ul class=\"fig-list\">\n<li>Transmissionen auf den Ziel-TPs werden bereits während des laufenden Empfangs getriggert (<code>CanTp_Transmit</code> / <code>LinTp_Transmit</code> nach erstem <code>CopyRxData</code>).</li>\n<li>Die lokale Weiterleitung an das Dcm (<code>Dcm_StartOfReception</code>) startet erst nach vollständigem Abschluss des Eingangs-TP-Transfers (<code>PduR_J1939TpRxIndication</code>).</li>\n<li>PduR puffert die Gesamt-PDU, um unterschiedliche Busgeschwindigkeiten, Segmentierungsgrößen und Bestätigungszeitpunkte von CanTp, LinTp und Dcm zu entkoppeln. Pufferfreigabe darf erst nach Eingang aller TxConfirmations bzw. RxIndications erfolgen.</li>\n</ul>"}], "trans": [{"from": "FIG-d5d5e89790d2d945", "to": "FIG-225a438c0589146b", "fr": "R21-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Kopfbereich der Lebenslinie «module» Dcm: Das Unendlich- bzw. Zersetzungssymbol unter dem Modulnamen wurde entfernt.</li>\n</ul>"}]};
